public class ExFlow {
 public List<String> trail=new List<String>();
 public Integer choose(Integer mode){
  try {trail.add('try'); if(mode==1){throw new ExProbeException('flow');} if(mode==2){return 2;} return 1;}
  catch(ExProbeException e){trail.add('catch');return 3;}
  finally {trail.add('finally');}
 }
 public void raise(String message){throw new ExProbeException(message);}
 public void throwNull(){ExProbeException e;throw e;}
 public void leaf(){throw new ExProbeException('leaf');}
 public void middle(){leaf();}
 public void rethrow(){try {leaf();}catch(ExProbeException e){throw e;}}
 public void wrap(){try {leaf();}catch(ExProbeException e){throw new ExOtherException('wrapped',e);}}
 public void nullLeaf(){String s; s.length();}
 public void conversionLeaf(){Integer.valueOf('not-an-integer');}
}

